    function dumpAll() {
        Java.perform(function () {
            Java.enumerateLoadedDexFiles({
                onMatch: function (dexFile) {
                    try {
                        // 新版梆梆在 .bss/.data 中解密 dex；用 ART 内部 dump
                        console.log("[+] loaded dex: " + dexFile);
                    } catch (e) {}
                },
                onComplete: function () {}
            });
        });
    }
    dumpAll();
});

// 2. 下钩 —— ART 加载 dex 的原生入口
var mods = Process.enumerateModules();
var libart = null;
mods.forEach(function (m) { if (m.name.indexOf("libart") >= 0) libart = m; });
if (libart) {
    ["_ZN3art11ClassLinker13DefineClassE","_ZN3art7DexFile4Open"].forEach(function (sym) {
        var addr = Module.findExportByName(libart.name, sym);
        if (addr) {
            Interceptor.attach(addr, {
                onEnter: function (args) {
                    // 扫内存中所有 dex magic: 6465780a
                    var ranges = Process.enumerateRanges('r--');
                    ranges.forEach(function (r) {
