    } while (Module32NextW(snap, &me));
    CloseHandle(snap); return 0;
}

template<class T> bool RPM(DWORD64 addr, T& out) {
    SIZE_T n = 0;
    return ReadProcessMemory(g_proc, (LPCVOID)addr, &out, sizeof(T), &n) && n == sizeof(T);
}

int main() {
