    RPM(g_base + [UWorld偏移], world);                  // 例 0x4A1B2C8
    printf("UWorld=%llX\n", world);

    DWORD64 localPawn = 0;
    RPM(world + [LocalPlayer偏移], localPawn);          // 例 0x2B8
    printf("LocalPawn=%llX\n", localPawn);

    // 实体列表头 + 数量
    DWORD64 entityList = 0; int count = 0;
    RPM(world + [EntityList偏移], entityList);
    RPM(world + [EntityCount偏移], count);
    printf("entities=%llX count=%d\n", entityList, count);
