```c
// 核心读写：用 MmCopyVirtualMemory 走内核态跨进程
static NTSTATUS DoCopy(HANDLE hTarget, ULONG64 addr, PVOID buf, SIZE_T size, BOOLEAN write, PSIZE_T done)
{
    PEPROCESS src = NULL, dst = NULL;
    NTSTATUS st = PsLookupProcessByProcessId(hTarget, &dst);
    if (!NT_SUCCESS(st)) return st;
    src = PsGetCurrentProcess();

    KAPC_STATE apc;
    // 目标进程必须是 dst，来源/去处按读写方向切换
    PEPROCESS from = write ? src : dst;
    PEPROCESS to   = write ? dst : src;
    PVOID     fromBuf = write ? buf : (PVOID)addr;
    PVOID     toBuf   = write ? (PVOID)addr : buf;

    KeStackAttachProcess(to, &apc);   // 关键：attach 到目标
    st = MmCopyVirtualMemory(from, fromBuf, to, toBuf, size, KernelMode, done);
    KeUnstackDetachProcess(&apc);

    ObDereferenceObject(dst);
    return st;
}
```

```c
// Dispatch 里分发（省略完整 IRP 管线，只给分发体）
NTSTATUS DispatchIoctl(PDEVICE_OBJECT dev, PIRP irp)
{
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(irp);
    PVOID inBuf = irp->AssociatedIrp.SystemBuffer;
    ULONG inLen = sp->Parameters.DeviceIoControl.InputBufferLength;
    NTSTATUS st = STATUS_INVALID_PARAMETER;
    SIZE_T done = 0;

    if (sp->Parameters.DeviceIoControl.IoControlCode == IOCTL_INIT_READ ||
        sp->Parameters.DeviceIoControl.IoControlCode == IOCTL_INIT_WRITE)
    {
        if (inLen >= sizeof(RW_REQUEST)) {
            PRW_REQUEST r = (PRW_REQUEST)inBuf;
            // 注意：Buffer 字段是用户态指针，驱动不能直接解引用，
            // 生产版要把数据经 MDL 或 ProbeForRead 拷到内核缓冲
            st = DoCopy((HANDLE)(ULONG_PTR)r->Pid, r->Address,
                        r->Buffer, r->Size,
                        sp->Parameters.DeviceIoControl.IoControlCode == IOCTL_INIT_WRITE,
                        &done);
            r->BytesDone = done;
        }
    }
    irp->IoStatus.Status = st;
    irp->IoStatus.Information = (inLen >= sizeof(RW_REQUEST)) ? sizeof(RW_REQUEST) : 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}
