```cpp
// step0_target_probe.cpp —— 先摸清进程与模块，后面所有偏移都挂在这个基址上
// build: cl /std:c++17 /EHsc step0_target_probe.cpp
#include <windows.h>
#include <tlhelp32.h>
#include <psapi.h>
#include <cstdio>
#include <vector>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe)) {
        if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
    }
    CloseHandle(snap);
    return pid;
}

// 模块枚举：拿 [模块名] 的基址与大小，透视用的 GWorld/实体表都从这里算
static uintptr_t ModuleBase(DWORD pid, const wchar_t* mod, size_t* outSize=nullptr) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me)) {
        if (_wcsicmp(me.szModule, mod) == 0) {
            base = (uintptr_t)me.modBaseAddr;
            if (outSize) *outSize = me.modBaseSize;
            break;
        }
    }
    CloseHandle(snap);
    return base;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* proc = argc > 1 ? argv[1] : L"[进程名].exe";
    const wchar_t* mod  = argc > 2 ? argv[2] : L"[模块名].exe";

    DWORD pid = FindPid(proc);
    if (!pid) { wprintf(L"[!] 进程未运行: %s\n", proc); return 1; }

    HANDLE h = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, pid);
    if (!h) { wprintf(L"[!] OpenProcess 失败 %lu（检查提权 / 反作弊句柄保护）\n", GetLastError()); return 2; }

    size_t modSize = 0;
    uintptr_t base = ModuleBase(pid, mod, &modSize);
    wprintf(L"[+] pid=%lu  %s base=0x%llX size=0x%zX\n",
            pid, mod, (unsigned long long)base, modSize);

    if (!base) { CloseHandle(h); return 3; }

    // 读 DOS/NT 头确认读权限是否真的生效——很多保护会在这里拦下
    IMAGE_DOS_HEADER dos{}; SIZE_T got = 0;
    if (ReadProcessMemory(h, (LPCVOID)base, &dos, sizeof(dos), &got) && dos.e_magic == IMAGE_DOS_SIGNATURE) {
        IMAGE_NT_HEADERS64 nt{};
        ReadProcessMemory(h, (LPCVOID)(base + dos.e_lfanew), &nt, sizeof(nt), &got);
        wprintf(L"[+] PE ok  TimeDateStamp=0x%08X  ImageBase=0x%llX  Entry=0x%llX\n",
                nt.FileHeader.TimeDateStamp,
                (unsigned long long)nt.OptionalHeader.ImageBase,
                (unsigned long long)(base + nt.OptionalHeader.AddressOfEntryPoint));

        // 输出节区表，后面 .text/.rdata 的特征码扫描要用到节区间
        auto sec = (PIMAGE_SECTION_HEADER)((BYTE*)&nt + sizeof(IMAGE_NT_HEADERS64));
        for (int i = 0; i < nt.FileHeader.NumberOfSections; ++i) {
            char nm[9]{}; memcpy(nm, sec[i].Name, 8);
            wprintf(L"    sec %-8S VA=0x%08X VSize=0x%08X\n",
                    nm, sec[i].VirtualAddress, sec[i].Misc.VirtualSize);
        }
    } else {
        wprintf(L"[!] ReadProcessMemory 被拦（err=%lu）→ 走驱动级读写路径\n", GetLastError());
    }

    CloseHandle(h);
    return 0;
}
```

**这一步定义了什么**：`pid` → `[模块名]` 基址 → 节区表。透视需要的三样东西（`UWorld` / 实体列表 / 相机矩阵）全部是 `base + [偏移]` 的派生，所以基址拿不到，后面全是空谈。

