`Driver.c` — 建立设备 + IOCTL 通道，用 `MmCopyVirtualMemory` 做跨进程读写：

```c
#include <ntifs.h>
#include <ntddk.h>

#define DEVICE_NAME     L"\\Device\\[驱动名]"
#define SYMLINK_NAME    L"\\DosDevices\\[驱动名]"
#define IOCTL_READ      CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_WRITE     CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_GETBASE   CTL_CODE(FILE_DEVICE_UNKNOWN, 0x802, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _RW_REQUEST {
    ULONG   Pid;
    PVOID   Address;         // 目标进程虚拟地址
    PVOID   Buffer;          // 用户态缓冲（用户侧填指针时需先 ProbeForRead/Write）
    SIZE_T  Size;
    SIZE_T  Returned;
    WCHAR   ModuleName[64];   // 用于 GETBASE
    PVOID   ModuleBase;
} RW_REQUEST, *PRW_REQUEST;

// 通过 EPROCESS 拿到目标进程对象
static PEPROCESS GetTargetProcess(ULONG Pid) {
    PEPROCESS proc = NULL;
    if (NT_SUCCESS(PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)Pid, &proc)))
        return proc;
    return NULL;
}

static NTSTATUS DoReadWrite(PRW_REQUEST req, BOOLEAN Write) {
    PEPROCESS target = GetTargetProcess(req->Pid);
    if (!target) return STATUS_NOT_FOUND;

    // 通过当前进程拿到自身 PEPROCESS 引用（KPROCESS 的当前线程拿 PEPROCESS）
    PEPROCESS src = PsGetCurrentProcess(); // 当前调用的就是用户态发起方

    SIZE_T copied = 0;
    NTSTATUS st = STATUS_SUCCESS;

    if (Write) {
        // 用户态 buffer -> 目标进程 address
        st = MmCopyVirtualMemory(src, req->Buffer, target, req->Address,
                                 req->Size, KernelMode, &copied);
    } else {
        // 目标进程 address -> 用户态 buffer
        st = MmCopyVirtualMemory(target, req->Address, src, req->Buffer,
                                 req->Size, KernelMode, &copied);
    }
    req->Returned = copied;
    ObDereferenceObject(target);
    return st;
}

static NTSTATUS GetModuleBase(PRW_REQUEST req) {
    PEPROCESS target = GetTargetProcess(req->Pid);
    if (!target) return STATUS_NOT_FOUND;

    // 拿 PEB / Ldr
    KAPC_STATE apc;
    KeStackAttachProcess(target, &apc);
    NTSTATUS st = STATUS_NOT_FOUND;
    __try {
        PPEB peb = PsGetProcessPeb(target);
        if (peb && peb->Ldr) {
            PLIST_ENTRY head = &peb->Ldr->InMemoryOrderModuleList;
            for (PLIST_ENTRY e = head->Flink; e != head; e = e->Flink) {
                PLDR_DATA_TABLE_ENTRY entry = CONTAINING_RECORD(e, LDR_DATA_TABLE_ENTRY, InMemoryOrderLinks);
                if (entry->BaseDllName.Buffer) {
                    if (_wcsnicmp(entry->BaseDllName.Buffer, req->ModuleName, 63) == 0) {
                        req->ModuleBase = entry->DllBase;
                        st = STATUS_SUCCESS;
                        break;
                    }
                }
            }
        }
    } __except (EXCEPTION_EXECUTE_HANDLER) { st = GetExceptionCode(); }
    KeUnstackDetachProcess(&apc);
    ObDereferenceObject(target);
    return st;
}

