**2. 内核驱动骨架（WDM，手动映射器）**

```c
// ace_injector.c —— 占位符：g_TargetPid / g_pImageBase / g_ImageSize
#include <ntifs.h>
#include <ntimage.h>

typedef struct _INJECT_CTX {
    HANDLE  TargetPid;
    PVOID   ImageBase;
    SIZE_T  ImageSize;
} INJECT_CTX, *PINJECT_CTX;

NTSTATUS MapImageToProcess(INJECT_CTX* ctx)
{
    PEPROCESS target = NULL;
    NTSTATUS st = PsLookupProcessByProcessId(ctx->TargetPid, &target);
    if (!NT_SUCCESS(st)) return st;

    KAPC_STATE apc;
    KeStackAttachProcess(target, &apc);

    PVOID remote = NULL;
    SIZE_T size  = ctx->ImageSize;
    st = ZwAllocateVirtualMemory(ZwCurrentProcess(), &remote, 0, &size,
                                 MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (NT_SUCCESS(st)) {
        // 逐节复制 + 重定位 + 导入表修复在下面第 3 段
        RtlCopyMemory(remote, ctx->ImageBase, ctx->ImageSize);
    }

    KeUnstackDetachProcess(&apc);
    ObDereferenceObject(target);
    return st;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT drv, PUNICODE_STRING reg)
{
    UNREFERENCED_PARAMETER(reg);
    drv->DriverUnload = NULL;          // 手动映射进内核，无卸载
    INJECT_CTX ctx = { 0 };
    ctx.TargetPid = ULongToHandle([目标PID]);
    ctx.ImageBase = [载荷映像基址];
    ctx.ImageSize = [载荷大小];
    return MapImageToProcess(&ctx);
}
```

`KeStackAttachProcess` + `ZwAllocateVirtualMemory` 这一对是绕 `ObRegisterCallbacks` 剥权限的关键：走的是内核态附加，不经过用户态 `OpenProcess` 的句柄校验回调。

**3. 载荷要做的三件事（写进 `MapImageToProcess` 里）**

- 节表遍历：`IMAGE_FIRST_SECTION` → `MEM_COMMIT` 每节按 `Characteristics` 设 `PAGE_EXECUTE_READ` / `PAGE_READWRITE`；
- 重定位：`IMAGE_DIRECTORY_ENTRY_BASERELOC`，目标基址与 `ImageBase` 不同就逐块 `IMAGE_REL_BASED_DIR64` 加 delta；
- 导入表：`IMAGE_DIRECTORY_ENTRY_IMPORT`，`LdrLoadDll` / 自己解析 `PEB->Ldr` 拿 `GetProcAddress` 等价物，别用 `MmGetSystemRoutineAddress` 去解析用户态 DLL 的导出。

