// rw.c —— 编译: cl /O2 rw.c /link /out:rw.exe  (x64 Developer Prompt)
#include <windows.h>
#include <stdio.h>
#include <tlhelp32.h>

static DWORD GetPid(const char* name) {
    HANDLE h = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32 pe = { sizeof(pe) };
    for (BOOL ok = Process32First(h, &pe); ok; ok = Process32Next(h, &pe))
        if (!_stricmp(pe.szExeFile, name)) { DWORD pid = pe.th32ProcessID; CloseHandle(h); return pid; }
    CloseHandle(h); return 0;
}

static ULONG_PTR GetModBase(DWORD pid, const char* mod) {
    HANDLE h = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32 me = { sizeof(me) };
    for (BOOL ok = Module32First(h, &me); ok; ok = Module32Next(h, &me))
        if (!_stricmp(me.szModule, mod)) { ULONG_PTR b = (ULONG_PTR)me.modBaseAddr; CloseHandle(h); return b; }
    CloseHandle(h); return 0;
}

int main(int argc, char** argv) {
    const char* proc = argc > 1 ? argv[1] : "[进程名].exe";
    const char* mod  = argc > 2 ? argv[2] : "[模块名].exe";
    DWORD pid = GetPid(proc);
    if (!pid) { printf("[!] pid not found: %s\n", proc); return 1; }
    HANDLE ph = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!ph) { printf("[!] OpenProcess failed: %lu\n", GetLastError()); return 1; }
    ULONG_PTR base = GetModBase(pid, mod);
    printf("[+] pid=%lu base=%p\n", pid, (void*)base);

    // 多级指针链读: base + [偏移1] -> +[偏移2] -> 读值
    ULONG_PTR addr = base + 0x[偏移1];
    ULONG_PTR p1 = 0, p2 = 0;
    ReadProcessMemory(ph, (LPCVOID)addr, &p1, 8, NULL);
    p2 = p1 + 0x[偏移2];
    int val = 0;
    ReadProcessMemory(ph, (LPCVOID)p2, &val, 4, NULL);
    printf("[+] chain: %p -> %p -> value=%d\n", (void*)addr, (void*)p2, val);

    // ★ 改值前先 dump 原值（回滚依据）
    int orig = val;
    int newv = 999999;
    WriteProcessMemory(ph, (LPVOID)p2, &newv, 4, NULL);  // 验证: 改后看界面是否变化
    ReadProcessMemory(ph, (LPCVOID)p2, &val, 4, NULL);
    printf("[+] after write: %d (orig=%d, 回滚用)\n", val, orig);
    // 回滚: WriteProcessMemory(ph, (LPVOID)p2, &orig, 4, NULL);
    CloseHandle(ph);
    return 0;
}
