```cpp
// base.h
#pragma once
#include <windows.h>
#include <tlhelp32.h>
#include <string>

static DWORD FindPid(const wchar_t* name) {
    HANDLE h = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    if (Process32FirstW(h, &pe)) do {
        if (!_wcsicmp(pe.szExeFile, name)) { CloseHandle(h); return pe.th32ProcessID; }
    } while (Process32NextW(h, &pe));
    CloseHandle(h); return 0;
}

static uintptr_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE h = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    if (Module32FirstW(h, &me)) do {
        if (!_wcsicmp(me.szModule, mod)) { CloseHandle(h); return (uintptr_t)me.modBaseAddr; }
    } while (Module32NextW(h, &me));
    CloseHandle(h); return 0;
}
```

## 2. 读写封装（`ReadProcessMemory` / `WriteProcessMemory`）

```cpp
// rw.h
#pragma once
#include "base.h"

struct Proc {
    HANDLE h{};
    DWORD pid{};
    uintptr_t base{};
    bool Attach(const wchar_t* exe, const wchar_t* mod) {
        pid = FindPid(exe);
        if (!pid) return false;
        h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE |
                        PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
        if (!h) return false;
        base = GetModuleBase(pid, mod);
        return base != 0;
    }
    template<class T> bool R(uintptr_t addr, T& out) {
        SIZE_T n{}; return ReadProcessMemory(h, (LPCVOID)addr, &out, sizeof(T), &n) && n == sizeof(T);
    }
    template<class T> bool W(uintptr_t addr, const T& in) {
        SIZE_T n{}; return WriteProcessMemory(h, (LPVOID)addr, &in, sizeof(T), &n) && n == sizeof(T);
    }
    // 多级指针链：offsets 从高到低，最后一级是字段偏移
    uintptr_t Chain(uintptr_t baseAddr, const std::initializer_list<uintptr_t>& offsets) {
        uintptr_t cur = baseAddr;
        auto it = offsets.begin();
        for (; it != offsets.end(); ++it) {
            uintptr_t next{};
            if (!R(cur, next)) return 0;
            cur = next + *it;
        }
        return cur;
    }
};
```

