static void DumpModules(HANDLE hProc, DWORD pid) {
    HMODULE mods[1024]; DWORD need = 0;
    if (EnumProcessModulesEx(hProc, mods, sizeof(mods), &need, LIST_MODULES_ALL)) {
        for (DWORD i = 0; i < need / sizeof(HMODULE); ++i) {
            MODULEINFO mi{};
            if (GetModuleInformation(hProc, mods[i], &mi, sizeof(mi))) {
                wchar_t base[MAX_PATH]{};
                GetModuleBaseNameW(hProc, mods[i], base, MAX_PATH);
                wprintf(L"%-40s base=%p size=0x%08X\n", base, mi.lpBaseOfDll, mi.SizeOfImage);
            }
        }
    }
}

// 多级指针链解析：base + [offsets...]
static uintptr_t FollowChain(HANDLE hProc, uintptr_t moduleBase, const std::vector<uintptr_t>& offsets) {
    uintptr_t addr = moduleBase;
    for (size_t i = 0; i < offsets.size(); ++i) {
        uintptr_t next = 0;
        if (!ReadProcessMemory(hProc, (LPCVOID)(addr + offsets[i]), &next, sizeof(next), nullptr)) {
            printf("[!] read fail at 0x%llX + 0x%llX (level %zu)\n",
                   (unsigned long long)addr, (unsigned long long)offsets[i], i);
            return 0;
        }
        addr = next;
        printf("  L%zu: 0x%llX -> 0x%llX\n", i, (unsigned long long)(addr), (unsigned long long)next);
    }
    return addr;
}

