    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    ULONG_PTR b = 0;
    if (Module32FirstW(snap, &me)) do {
        if (!_wcsicmp(me.szModule, mod)) { b = (ULONG_PTR)me.modBaseAddr; break; }
    } while (Module32NextW(snap, &me));
    CloseHandle(snap);
    return b;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* proc = argc > 1 ? argv[1] : L"[进程名].exe";
    const wchar_t* mod  = argc > 2 ? argv[2] : L"[模块名].exe";

    DWORD pid = FindPid(proc);
    if (!pid) { wprintf(L"pid not found: %ls\n", proc); return 1; }
    wprintf(L"pid=%lu\n", pid);

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess failed: %lu\n", GetLastError()); return 1; }

    ULONG_PTR base = ModBase(pid, mod);
    wprintf(L"module base = 0x%llX\n", (unsigned long long)base);

    // 多级指针链：先读基址，逐级解引用
    const ULONG_PTR offList[] = { 0x[偏移0], 0x[偏移1], 0x[偏移2] }; // 从静态基址开始的链
    ULONG_PTR addr = base;
    for (ULONG_PTR off : offList) {
        ULONG_PTR next = 0;
