    int orig = 0;
    ReadProcessMemory(h, (LPCVOID)(addr + 0x[值偏移]), &orig, sizeof(orig), nullptr);
    wprintf(L"orig value = %d\n", orig);

    int nv = [目标值];
    WriteProcessMemory(h, (LPVOID)(addr + 0x[值偏移]), &nv, sizeof(nv), nullptr);
    wprintf(L"written, now value = %d\n", nv);

