```cpp
// aim_skeleton_step0.cpp  —  x64, MSVC / MinGW 均可编译
// 作用：枚举 [进程名] 的模块基址，输出模块列表 + 主模块大小，供后续 W2S / 骨骼偏移定位
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>
#include <string>

struct ModInfo { std::wstring name; uintptr_t base; size_t size; };

static DWORD FindPid(const wchar_t* procName) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, procName) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

static std::vector<ModInfo> ListModules(DWORD pid) {
    std::vector<ModInfo> out;
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    if (snap == INVALID_HANDLE_VALUE) return out;
    MODULEENTRY32W me{ sizeof(me) };
    if (Module32FirstW(snap, &me)) {
        do {
            out.push_back({ me.szModule, (uintptr_t)me.modBaseAddr, (size_t)me.modBaseSize });
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return out;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* target = (argc > 1) ? argv[1] : L"[进程名].exe";
    DWORD pid = FindPid(target);
    if (!pid) { wprintf(L"[!] 未找到进程: %s\n", target); return 1; }
    wprintf(L"[+] PID = %lu\n", pid);

    HANDLE h = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, pid);
    if (!h) { wprintf(L"[!] OpenProcess 失败 err=%lu\n", GetLastError()); return 2; }

    wchar_t path[MAX_PATH]{};
    DWORD sz = MAX_PATH;
    if (QueryFullProcessImageNameW(h, 0, path, &sz))
        wprintf(L"[+] Image  = %s\n", path);
    CloseHandle(h);

    auto mods = ListModules(pid);
    wprintf(L"[+] 模块数 = %zu\n", mods.size());
    for (auto& m : mods)
        wprintf(L"    %-40s base=0x%016llX size=0x%zX\n",
                m.name.c_str(), (unsigned long long)m.base, m.size);
    return 0;
}
